# this_file: tests/test_print_guide.py
"""Regression checks for the tracked guide generated by the documentation build."""

from html.parser import HTMLParser
from pathlib import Path


class GuideLinks(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.ids: set[str] = set()
        self.fragments: set[str] = set()
        self.chapters: list[str] = []

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        attributes = dict(attrs)
        if element_id := attributes.get("id"):
            self.ids.add(element_id)
            if tag == "section" and attributes.get("class") == "print-page":
                self.chapters.append(element_id)
        href = attributes.get("href") or ""
        if tag == "a" and href.startswith("#") and len(href) > 1:
            self.fragments.add(href[1:])


def test_print_guide_includes_chapters_and_resolves_fragment_links() -> None:
    root = Path(__file__).resolve().parents[1]
    guide = GuideLinks()
    guide.feed((root / "docs/print_page/index.html").read_text(encoding="utf-8"))
    chapters = {page.stem for page in (root / "src_docs").glob("*.md")} - {"print_page"}
    assert set(guide.chapters) == chapters
    assert len(guide.chapters) == len(chapters)
    assert chapters <= guide.fragments
    assert not guide.fragments - guide.ids, f"Missing guide anchors: {guide.fragments - guide.ids}"
